sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.cah-hero {
  min-height: 580px;
  width: 100%;

  display: flex;
  align-items: center;
  justify-content: center;

  text-align: center;

  background: linear-gradient(135deg, #eff6ff, #f8fafc);

  font-family: Arial, sans-serif;
}

.hero-content {
  max-width: 850px;
  padding: 80px 20px;
}

.hero-badge {
  display: inline-block;

  padding: 8px 16px;
  margin-bottom: 22px;

  background: #dbeafe;
  color: #2563eb;

  border-radius: 20px;

  font-size: 12px;
  font-weight: bold;
  letter-spacing: 1px;
}

.hero-content h1 {
  margin: 0;

  color: #111827;

  font-size: 52px;
  font-weight: 700;

  line-height: 1.15;
}

.hero-content h1 span {
  display: block;
  color: #2563eb;
}

.hero-content p {
  max-width: 720px;

  margin: 25px auto;

  color: #6b7280;

  font-size: 19px;
  line-height: 1.6;
}

.hero-buttons {
  display: flex;
  justify-content: center;
  gap: 15px;

  margin-top: 30px;
}

.hero-buttons button {
  border: none;

  padding: 14px 25px;

  border-radius: 8px;

  background: #2563eb;
  color: white;

  font-size: 15px;
  font-weight: bold;

  cursor: pointer;
}

.hero-buttons button:hover {
  background: #1d4ed8;
}

.hero-buttons .secondary-btn {
  background: white;
  color: #2563eb;

  border: 1px solid #2563eb;
}

.hero-users {
  margin-top: 28px;

  color: #6b7280;

  font-size: 14px;
}

.hero-users span {
  margin: 0 8px;
  color: #2563eb;
}

@media (max-width: 768px) {

  .hero-content h1 {
    font-size: 36px;
  }

  .hero-buttons {
    flex-direction: column;
  }
}
